const results = [];
for (const inputItem of $input.all()) {
  const metrics = inputItem.json?.data || [];
  if (!metrics || metrics.length === 0) continue;

  let mediaId = '';
  let views = 0;
  let reach = 0;
  let totalInteractions = 0;
  let likes = 0;
  let comments = 0;
  let shares = 0;
  let saved = 0;

  for (const item of metrics) {
    if (!mediaId && item.id) {
      mediaId = item.id.split('/')[0];
    }
    const val = (item.values && item.values.length > 0) ? Number(item.values[0].value) || 0 : 0;
    switch (item.name) {
      case 'views': views = val; break;
      case 'reach': reach = val; break;
      case 'total_interactions': totalInteractions = val; break;
      case 'likes': likes = val; break;
      case 'comments': comments = val; break;
      case 'shares': shares = val; break;
      case 'saved': saved = val; break;
    }
  }

  results.push({
    json: {
      platform: 'instagram',
      video_id: mediaId,
      views,
      reach,
      total_interactions: totalInteractions,
      likes,
      comments,
      shares,
      saved
    }
  });
}

if (results.length === 0) {
  return [{ json: { platform: 'instagram', video_id: 'none', views: 0, reach: 0, total_interactions: 0, likes: 0, comments: 0, shares: 0, saved: 0, note: 'No videos uploaded in the past 3 days' } }];
}

return results;

const results = [];
for (const inputItem of $input.all()) {
  const metrics = inputItem.json?.data || [];
  if (!metrics || metrics.length === 0) continue;

  let videoId = '';
  let plays = 0;
  let avgWatchTimeMs = 0;
  let comments = 0;
  let reactions = 0;
  let shares = 0;

  for (const item of metrics) {
    if (!videoId && item.id) {
      videoId = item.id.split('/')[0];
    }
    const firstValue = (item.values && item.values.length > 0) ? item.values[0].value : null;
    switch (item.name) {
      case 'fb_reels_total_plays':
        plays = Number(firstValue) || 0;
        break;
      case 'post_video_avg_time_watched':
        avgWatchTimeMs = Number(firstValue) || 0;
        break;
      case 'post_video_social_actions':
        if (typeof firstValue === 'object' && firstValue !== null) {
          comments = firstValue.COMMENT || 0;
          shares = firstValue.SHARE || 0;
          reactions = (firstValue.LIKE || 0) + (firstValue.REACTION || 0);
        }
        break;
    }
  }

  results.push({
    json: {
      platform: 'facebook',
      video_id: videoId,
      plays,
      avg_watch_time_seconds: Number((avgWatchTimeMs / 1000).toFixed(2)),
      comments,
      shares,
      reactions
    }
  });
}

if (results.length === 0) {
  return [{ json: { platform: 'facebook', video_id: 'none', plays: 0, avg_watch_time_seconds: 0, comments: 0, shares: 0, reactions: 0, note: 'No videos uploaded in the past 3 days' } }];
}

return results;

function parseIsoDuration(durationStr) {
  if (!durationStr) return 0;
  const match = durationStr.match(/PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?/);
  if (!match) return 0;
  const hours = parseInt(match[1] || 0, 10);
  const minutes = parseInt(match[2] || 0, 10);
  const seconds = parseInt(match[3] || 0, 10);
  return (hours * 3600) + (minutes * 60) + seconds;
}

const results = [];
for (const item of $input.all()) {
  const json = item.json || {};
  if (!json.snippet && !json.statistics) continue;
  const snippet = json.snippet || {};
  const stats = json.statistics || {};
  const content = json.contentDetails || {};

  results.push({
    json: {
      platform: 'youtube',
      video_id: json.id || 'unknown',
      title: snippet.title || '',
      views: Number(stats.viewCount) || 0,
      likes: Number(stats.likeCount) || 0,
      comments: Number(stats.commentCount) || 0,
      duration_seconds: parseIsoDuration(content.duration)
    }
  });
}

if (results.length === 0) {
  return [{ json: { platform: 'youtube', video_id: 'none', title: 'None', views: 0, likes: 0, comments: 0, duration_seconds: 0, note: 'No videos uploaded in the past 3 days' } }];
}

return results;

const collectionTime = new Date().toISOString();
const allMetrics = $input.all().map(item => item.json);

return [{
  json: {
    collected_at: collectionTime,
    snapshot_data: JSON.stringify(allMetrics)
  }
}];

const currentItems = $('Aggregate').first().json.data || [];
const historyRows = $input.all().map(item => item.json);

const sorted = historyRows
  .filter(r => r.collected_at || r['collected at'])
  .sort((a, b) => new Date(b.collected_at || b['collected at']) - new Date(a.collected_at || a['collected at']));

const currentTimestamp = $('Prepare Snapshot Data').first().json.collected_at;
const previousRows = sorted.filter(r => (r.collected_at || r['collected at']) !== currentTimestamp).slice(0, 2);

function safeParse(val) {
  if (!val) return [];
  if (Array.isArray(val)) return val;
  if (typeof val === 'object') return val;
  try { return JSON.parse(val); } catch (e) {
    return [];
  }
}

const prevSnapshots = previousRows.map(r => ({
  collected_at: r.collected_at || r['collected at'],
  records: safeParse(r.snapshot_data)
}));

const igCurrent = currentItems.filter(i => i.platform === 'instagram');
const fbCurrent = currentItems.filter(i => i.platform === 'facebook');
const ytCurrent = currentItems.filter(i => i.platform === 'youtube');

const igHistory = prevSnapshots.map(s => ({
  collected_at: s.collected_at,
  records: s.records.filter(i => i.platform === 'instagram')
}));

const fbHistory = prevSnapshots.map(s => ({
  collected_at: s.collected_at,
  records: s.records.filter(i => i.platform === 'facebook')
}));

const ytHistory = prevSnapshots.map(s => ({
  collected_at: s.collected_at,
  records: s.records.filter(i => i.platform === 'youtube')
}));

return [{
  json: {
    instagram: { current: igCurrent, history: igHistory },
    facebook: { current: fbCurrent, history: fbHistory },
    youtube: { current: ytCurrent, history: ytHistory }
  }
}];

const items = $input.all();
let igReport = '';
let fbReport = '';
let ytReport = '';

for (const item of items) {
  const text = item.json.output || item.json.text || JSON.stringify(item.json);
  if (text.includes('Instagram')) {
    igReport = text;
  } else if (text.includes('Facebook')) {
    fbReport = text;
  } else if (text.includes('YouTube')) {
    ytReport = text;
  }
}

if (!igReport && items[0]) igReport = items[0].json.output || items[0].json.text || '';
if (!fbReport && items[1]) fbReport = items[1].json.output || items[1].json.text || '';
if (!ytReport && items[2]) ytReport = items[2].json.output || items[2].json.text || '';

return [{
  json: {
    instagram_report: igReport,
    facebook_report: fbReport,
    youtube_report: ytReport
  }
}];

